# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _require_email(stud: Student) -> None:
    if not stud.email:
        raise ProjectError(
            f"no email for student {stud.display_name}"
        )


def _validated(
    students: Iterable[Student]
) -> List[Student]:
    ordered = sorted(
        students, key=lambda stud: stud.display_name
    )
    if not ordered:
        raise ProjectError("no students for the sheet")
    for stud in ordered:
        _require_email(stud)
    return ordered


def _pad(line: tuple, widths: List[int]) -> str:
    padded = (
        item.ljust(wide) for item, wide in zip(line, widths)
    )
    return "  ".join(padded).rstrip()


def _columns(cells: List[tuple]) -> List[str]:
    widths = [max(map(len, colm)) for colm in zip(*cells)]
    return [_pad(line, widths) for line in cells]


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Text rows of name, section and email, sorted by name.

    Raises ProjectError for an empty list or for a student
    without an email, naming that student.
    """
    ordered = _validated(students)
    return _columns(
        [(stud.display_name, stud.section, stud.email)
         for stud in ordered]
    )

