# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def make_student(last, first, section, email):
    return Student("id", last, first, section, email)


class ContactRowsTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            make_student("Young", "Al", "B", "al@x.org"),
            make_student("Adams", "Beth", "10", "b@x.org")
        ])
        self.assertEqual(rows, [
            "Adams, Beth  10  b@x.org",
            "Young, Al    B   al@x.org"
        ])

    def test_missing_email_names_student(self):
        stud = make_student("Adams", "Beth", "A", None)
        with self.assertRaises(ProjectError) as caught:
            contact_rows([stud])
        self.assertIn("Adams, Beth", str(caught.exception))

    def test_blank_email_rejected(self):
        stud = make_student("Adams", "Beth", "A", "")
        with self.assertRaises(ProjectError):
            contact_rows([stud])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
